    fun text(key: String, language: JarvisLanguage): String =
        translations[key]?.getOrNull(languages.indexOf(language)) ?: key
    fun hasAllLanguages(key: String): Boolean = translations[key]?.size == 7
    fun keys(): Set<String> = translations.keys
